initJs:
function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistories = [];
  let filteredHistories = [];

  const tbody = container.querySelector("#history-tbody");
  const modal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    const users = await window.aivicApi.list(0); // ログインユーザーテーブル
    const userSelect = container.querySelector("#select-user");
    if (users) {
      users.forEach(user => {
        const option = document.createElement("option");
        option.value = user.ユーザー名 || "";
        option.textContent = user.ユーザー名 || "";
        userSelect.appendChild(option);
      });
    }
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return "";
    const date = new Date(dateStr);
    return date.toLocaleString("ja-JP");
  }

  function renderRows(histories) {
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageHistories = histories.slice(startIndex, endIndex);

    if (pageHistories.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
    } else {
      tbody.innerHTML = pageHistories.map(h => `
        <tr data-id="${h.操作履歴ID || h.id || ''}">
          <td>${formatDateTime(h.操作日時)}</td>
          <td>${h.ユーザー名 || ""}</td>
          <td>${h.操作種別 || ""}</td>
          <td>${h.操作画面 || ""}</td>
          <td>${h.IPアドレス || ""}</td>
          <td><span style="color: ${h.処理結果 === '成功' ? '#4ade80' : h.処理結果 === '失敗' || h.処理結果 === 'エラー' ? '#f87171' : 'var(--text)'}">${h.処理結果 || ""}</span></td>
          <td><button class="action-btn secondary detail-btn" data-id="${h.操作履歴ID || h.id || ''}">詳細</button></td>
        </tr>
      `).join("");
    }

    updatePagination(histories.length);
  }

  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector("#page-info");
    const btnPrev = container.querySelector("#btn-prev");
    const btnNext = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${Math.max(1, totalPages)}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  function filterHistories() {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const user = container.querySelector("#select-user").value;
    const operationType = container.querySelector("#select-operation-type").value;
    const screenName = container.querySelector("#input-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#input-ip-address").value;
    const result = container.querySelector("#select-result").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。");
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIPAddress(ipAddress)) {
      alert("不正なIPアドレス形式です。正しい形式で入力してください。");
      return;
    }

    filteredHistories = allHistories.filter(h => {
      if (startDate && h.操作日時 && new Date(h.操作日時) < new Date(startDate)) return false;
      if (endDate && h.操作日時 && new Date(h.操作日時) > new Date(endDate + "T23:59:59")) return false;
      if (user && h.ユーザー名 !== user) return false;
      if (operationType && h.操作種別 !== operationType) return false;
      if (screenName && !h.操作画面?.toLowerCase().includes(screenName)) return false;
      if (ipAddress && h.IPアドレス !== ipAddress) return false;
      if (result && h.処理結果 !== result) return false;
      return true;
    });

    currentPage = 1;
    renderRows(filteredHistories);
  }

  function isValidIPAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip);
  }

  function clearFilters() {
    container.querySelector("#input-start-date").value = "";
    container.querySelector("#input-end-date").value = "";
    container.querySelector("#select-user").value = "";
    container.querySelector("#select-operation-type").value = "";
    container.querySelector("#input-screen-name").value = "";
    container.querySelector("#input-ip-address").value = "";
    container.querySelector("#select-result").value = "";

    filteredHistories = [...allHistories];
    currentPage = 1;
    renderRows(filteredHistories);
  }

  function showDetailModal(historyId) {
    const history = allHistories.find(h => (h.操作履歴ID || h.id) === historyId);
    if (!history) return;

    detailContent.innerHTML = `
      <div style="display: grid; gap: 12px;">
        <div><strong>操作日時:</strong> ${formatDateTime(history.操作日時)}</div>
        <div><strong>ユーザー名:</strong> ${history.ユーザー名 || ""}</div>
        <div><strong>操作種別:</strong> ${history.操作種別 || ""}</div>
        <div><strong>操作画面:</strong> ${history.操作画面 || ""}</div>
        <div><strong>操作対象テーブル:</strong> ${history.操作対象テーブル || ""}</div>
        <div><strong>操作対象ID:</strong> ${history.操作対象ID || ""}</div>
        <div><strong>操作内容:</strong> ${history.操作内容 || ""}</div>
        <div><strong>IPアドレス:</strong> ${history.IPアドレス || ""}</div>
        <div><strong>ユーザーエージェント:</strong> ${history.ユーザーエージェント || ""}</div>
        <div><strong>処理結果:</strong> <span style="color: ${history.処理結果 === '成功' ? '#4ade80' : history.処理結果 === '失敗' || history.処理結果 === 'エラー' ? '#f87171' : 'var(--text)'}">${history.処理結果 || ""}</span></div>
        ${history.エラーメッセージ ? `<div><strong>エラーメッセージ:</strong> ${history.エラーメッセージ}</div>` : ""}
        <div><strong>処理時間:</strong> ${history.処理時間 || ""}ms</div>
      </div>
    `;

    modal.classList.remove("hidden");
  }

  function exportCSV() {
    if (filteredHistories.length > 100000) {
      alert("データ量が多すぎるため、CSV出力でタイムアウトエラーが発生する可能性があります。検索条件を絞り込んでから再度お試しください。");
      return;
    }

    const headers = ["操作日時", "ユーザー名", "操作種別", "操作画面", "操作対象テーブル", "操作対象ID", "操作内容", "IPアドレス", "ユーザーエージェント", "処理結果", "エラーメッセージ", "処理時間"];
    const csvContent = [
      headers.join(","),
      ...filteredHistories.map(h => [
        `"${formatDateTime(h.操作日時)}"`,
        `"${h.ユーザー名 || ""}"`,
        `"${h.操作種別 || ""}"`,
        `"${h.操作画面 || ""}"`,
        `"${h.操作対象テーブル || ""}"`,
        `"${h.操作対象ID || ""}"`,
        `"${(h.操作内容 || "").replace(/"/g, '""')}"`,
        `"${h.IPアドレス || ""}"`,
        `"${(h.ユーザーエージェント || "").replace(/"/g, '""')}"`,
        `"${h.処理結果 || ""}"`,
        `"${(h.エラーメッセージ || "").replace(/"/g, '""')}"`,
        `"${h.処理時間 || ""}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `system_operation_history_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    const histories = await window.aivicApi.list(12); // システム操作履歴テーブル
    if (histories) {
      allHistories = histories.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
      filteredHistories = [...allHistories];
      renderRows(filteredHistories);
    } else {
      // 初期データを使用
      allHistories = (tables[12]?.records || []).sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
      filteredHistories = [...allHistories];
      renderRows(filteredHistories);
    }
  }

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", filterHistories);
  container.querySelector("#btn-clear").addEventListener("click", clearFilters);
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredHistories);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredHistories.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredHistories);
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    modal.classList.add("hidden");
  });

  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      modal.classList.add("hidden");
    }
  });

  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // 初期化
  loadUsers();
  loadData();
}
